const f = $input.first().json;
const pick = (k, l) => (f[k] !== undefined && f[k] !== null && f[k] !== '') ? f[k] : f[l];
const company = String(pick('company_name', 'Company Name') || '').trim();
const role = String(pick('job_role', 'Job Role') || '').trim();
const jd = String(pick('job_description', 'Job Description') || '').trim();
const url = String(pick('registration_url', 'Company Registration URL') || '').trim();
const minCgpa = parseFloat(String(pick('min_cgpa', 'Minimum CGPA')).replace(/[^0-9.]/g, ''));
const maxBacklogs = parseInt(String(pick('max_backlogs', 'Maximum Backlogs')).replace(/[^0-9]/g, ''), 10);
const year = parseInt(String(pick('graduation_year', 'Graduation Year')).replace(/[^0-9]/g, ''), 10);
const deadline = String(pick('deadline', 'Registration Deadline') || '').slice(0, 10);
const today = $now.setZone('Asia/Kolkata').toISODate();
const errors = [];
if (!company) errors.push('Company name is required');
if (!role) errors.push('Job role is required');
if (!/^https?:\/\//i.test(url)) errors.push('Registration URL must start with http(s)://');
if (isNaN(minCgpa) || minCgpa < 0 || minCgpa > 10) errors.push('Minimum CGPA must be between 0 and 10');
if (isNaN(maxBacklogs) || maxBacklogs < 0) errors.push('Maximum backlogs must be 0 or more');
if (isNaN(year) || year < 2000 || year > 2100) errors.push('Graduation year must be a 4-digit year');
if (!/^\d{4}-\d{2}-\d{2}$/.test(deadline)) errors.push('Deadline must be a valid date');
else if (deadline < today) errors.push('Deadline ' + deadline + ' is already in the past');
if (errors.length) throw new Error('Invalid company details: ' + errors.join('; '));

const branches = [...new Set(String(pick('eligible_branches', 'Eligible Branches') || '')
  .split(/[,;\/]+/).map(b => b.trim().toUpperCase()).filter(Boolean))];
if (!branches.length) throw new Error('Invalid company details: at least one eligible branch is required');
const slug = s => s.toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 24);
const companyId = slug(company) + '-' + slug(role) + '-' + year;

const formDescription = company + ' - ' + role + '\nCompany ID: ' + companyId +
  '\nDeadline: ' + deadline +
  '\n\nFirst complete your registration on the company portal: ' + url +
  '\nThen submit this form to confirm. Note: this form records your confirmation only; the placement cell may verify registration with the company.';
const formRequests = [
  { updateFormInfo: { info: { description: formDescription }, updateMask: 'description' } },
  { createItem: { item: { title: 'USN', questionItem: { question: { required: true, textQuestion: {} } } }, location: { index: 0 } } },
  { createItem: { item: { title: 'Full Name', questionItem: { question: { required: true, textQuestion: {} } } }, location: { index: 1 } } },
  { createItem: { item: { title: 'College Email', questionItem: { question: { required: true, textQuestion: {} } } }, location: { index: 2 } } },
  { createItem: { item: { title: 'Have you completed registration on the company portal?', questionItem: { question: { required: true, choiceQuestion: { type: 'RADIO', options: [ { value: 'Yes - I have registered on the company portal' }, { value: 'No - I am not interested in this drive' } ] } } } }, location: { index: 3 } } }
];

return [{ json: {
  company_id: companyId, company_name: company, job_role: role, job_description: jd,
  registration_url: url, min_cgpa: minCgpa, eligible_branches: branches.join(', '), branches,
  max_backlogs: maxBacklogs, graduation_year: year, deadline, created_on: today,
  form_requests: formRequests
} }];

const c = $('Prepare Company Details').first().json;
const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);
const col = (r, names) => { for (const n of names) { if (r[n] !== undefined && r[n] !== null && String(r[n]).trim() !== '') return r[n]; } return ''; };
const hasCol = names => rows.some(r => names.some(n => Object.prototype.hasOwnProperty.call(r, n)));
const statusCols = ['Placement_Status', 'Placement Status', 'PlacementStatus'];
const yearCols = ['Graduation_Year', 'Graduation Year', 'GraduationYear', 'Passing_Year', 'Batch'];
const hasStatus = hasCol(statusCols);
const hasYear = hasCol(yearCols);
const blocked = ['placed', 'opted out', 'opted-out', 'debarred', 'blocked', 'not interested'];
const allBranches = c.branches.includes('ALL');
const seen = new Set();
const students = [];
let excluded = 0;
for (const r of rows) {
  const usn = String(col(r, ['USN'])).trim().toUpperCase();
  const email = String(col(r, ['Email'])).trim();
  if (!usn || seen.has(usn) || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { excluded++; continue; }
  const dept = String(col(r, ['Department'])).trim().toUpperCase();
  const cgpa = parseFloat(String(col(r, ['CGPA'])).replace(/[^0-9.]/g, ''));
  const backlogs = parseInt(String(col(r, ['Backlogs']) || '0').replace(/[^0-9]/g, '') || '0', 10);
  const status = String(col(r, statusCols)).trim().toLowerCase();
  const year = parseInt(String(col(r, yearCols)).replace(/[^0-9]/g, ''), 10);
  const ok = (allBranches || c.branches.includes(dept))
    && !isNaN(cgpa) && cgpa >= c.min_cgpa
    && backlogs <= c.max_backlogs
    && !blocked.includes(status)
    && (!hasYear || year === c.graduation_year);
  if (!ok) { excluded++; continue; }
  seen.add(usn);
  students.push({ usn, name: String(col(r, ['Student_Name', 'Name'])).trim(), email, department: dept, cgpa, backlogs });
}
const warnings = [];
if (!hasStatus) warnings.push('No Placement Status column found in the master sheet - placement status was NOT checked.');
if (!hasYear) warnings.push('No Graduation Year column found in the master sheet - graduation year was NOT checked.');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const previewRows = students.slice(0, 150).map(s => '<tr><td>' + esc(s.usn) + '</td><td>' + esc(s.name) + '</td><td>' + esc(s.department) + '</td><td>' + s.cgpa + '</td><td>' + s.backlogs + '</td><td>' + esc(s.email) + '</td></tr>').join('');
const previewHtml = '<table border="1" cellpadding="4" cellspacing="0"><tr><th>USN</th><th>Name</th><th>Dept</th><th>CGPA</th><th>Backlogs</th><th>Email</th></tr>' + previewRows + '</table>' + (students.length > 150 ? '<p>...and ' + (students.length - 150) + ' more</p>' : '');
return [{ json: { company_id: c.company_id, eligible_count: students.length, total_students: rows.length, excluded_count: excluded, warnings, warnings_html: warnings.map(w => '<p style="color:#b45309"><b>Warning:</b> ' + w + '</p>').join(''), preview_html: previewHtml, students } }];

