const c = $('Prepare Company Details').first().json;
const ss = $('Create Company Spreadsheet').first().json;
const form = $('Create Google Form').first().json;
const replies = $('Add Form Questions').first().json.replies || [];
const qid = i => (replies[i] && replies[i].createItem && replies[i].createItem.questionId && replies[i].createItem.questionId[0]) || '';
const el = $('Find Eligible Students').first().json;
return [{ json: {
  company_id: c.company_id, company_name: c.company_name, job_role: c.job_role, job_description: c.job_description,
  registration_url: c.registration_url, min_cgpa: c.min_cgpa, eligible_branches: c.eligible_branches,
  max_backlogs: c.max_backlogs, graduation_year: c.graduation_year, deadline: c.deadline,
  spreadsheet_id: ss.spreadsheetId, spreadsheet_url: ss.spreadsheetUrl,
  form_id: form.formId, form_url: form.responderUri,
  q_usn: qid(1), q_name: qid(2), q_email: qid(3), q_confirm: qid(4),
  folder_id: $('Create Company Folder').first().json.id,
  eligible_count: el.eligible_count, status: 'Active', created_on: c.created_on,
  approved_at: $now.setZone('Asia/Kolkata').toISO()
} }];

const rec = $('Build Company Record').first().json;
const students = $('Find Eligible Students').first().json.students || [];
const now = $now.setZone('Asia/Kolkata').toISO();
return students.map(s => ({ json: {
  email_key: rec.company_id + '|' + s.usn,
  company_id: rec.company_id,
  usn: s.usn, name: s.name, email: s.email, department: s.department,
  cgpa: s.cgpa, backlogs: s.backlogs, added_on: now
} }));

const now = $now.setZone('Asia/Kolkata').toISO();
return $('Build Student Rows').all().map(i => ({ json: {
  email_key: i.json.email_key, company_id: i.json.company_id, usn: i.json.usn, name: i.json.name,
  email: i.json.email, department: i.json.department,
  status: 'Pending', student_confirmation: '', confirmed_at: '', response_id: '',
  reminders_sent: 0, last_reminder_on: '', last_updated: now,
  note: 'Form confirmation only - not proof of registration on the company portal'
} }));
